import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Main {
    static boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    public static void main(String[] args) throws IOException {
        String text = new String(System.in.readAllBytes(), StandardCharsets.UTF_8);
        int len = text.length();
        while (len > 0 && text.charAt(len - 1) == '\n') len--;
        char[] s = text.substring(0, len).toCharArray();
        List<Integer> at = new ArrayList<>();
        for (int i = 0; i < s.length; i++) if (isVowel(s[i])) at.add(i);
        if (!at.isEmpty()) {
            // vowel i takes the character of vowel i-1; the first takes the last
            char last = s[at.get(at.size() - 1)];
            for (int i = at.size() - 1; i > 0; i--) s[at.get(i)] = s[at.get(i - 1)];
            s[at.get(0)] = last;
        }
        System.out.print(new String(s) + "\n");
    }
}

package main

import (
	"io"
	"os"
	"strings"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	s := []byte(strings.TrimRight(string(data), "\n"))
	var at []int
	for i, c := range s {
		if strings.IndexByte("aeiou", c) >= 0 {
			at = append(at, i)
		}
	}
	if len(at) > 0 {
		// vowel i takes the character of vowel i-1; the first takes the last
		last := s[at[len(at)-1]]
		for i := len(at) - 1; i > 0; i-- {
			s[at[i]] = s[at[i-1]]
		}
		s[at[0]] = last
	}
	os.Stdout.Write(append(s, '\n'))
}
